{
  "company": "CRONUS International Ltd.",
  "messageType": "Help.WhoAmI.Get",
  "status": "Success",
  "contract": "json",
  "format": "chapters",
  "catalogue": {
    "name": "Help.WhoAmI.Get",
    "isEnabled": true,
    "filterTableNo": 0,
    "description": "Returns a comprehensive user profile for the current user, including roles, setup, and system prompt.",
    "selectionDescription": "Return who the caller is and what surrounds them: environment and company, user and language, linked resource, salesperson, employee and manager, approval and notification setup, unread notifications, pending approvals and the user's system prompt. Read-only, except that the first call creates the user's Bifrost user setup. Call it first in a session.",
    "messageDirection": "Outbound",
    "keywords": [
      "who am i",
      "my user",
      "my profile",
      "my language",
      "my company",
      "current user",
      "my approvals",
      "my notifications",
      "my employee",
      "my manager",
      "session start"
    ],
    "chargeable": false
  },
  "chapters": {
    "envelope": {
      "strict": {
        "type": "boolean",
        "required": false,
        "default": false,
        "description": "Optional root Boolean, default false. Non-read types always refuse unknown data keys before execution with UnknownParameter; false does not opt out. Read types warn unless strict is true. Do not place this option inside data."
      },
      "subject": {
        "use": "notUsed"
      },
      "dataRequired": false,
      "version": "1.0",
      "contentType": "text/json"
    },
    "response": {
      "contentType": "text/json",
      "fields": [
        {
          "name": "status",
          "type": "string",
          "description": "Success."
        },
        {
          "name": "bifrost",
          "type": "object",
          "description": "Installed Bifrost application metadata. Read-only; no HTTP.",
          "children": [
            {
              "name": "foundation",
              "type": "object",
              "description": "The installed Foundation application.",
              "children": [
                {
                  "name": "version",
                  "type": "string",
                  "description": "The full four-part installed Foundation app version, not the message contract version."
                },
                {
                  "name": "publishedAs",
                  "type": "string",
                  "description": "Global, PTE or Dev."
                }
              ]
            },
            {
              "name": "apps",
              "type": "array",
              "description": "Installed Origo applications that depend on Foundation, sorted by name. Empty when none. Includes test extensions if installed. No application identifiers or file paths.",
              "children": [
                {
                  "name": "name",
                  "type": "string",
                  "description": "The installed application name."
                },
                {
                  "name": "version",
                  "type": "string",
                  "description": "The full four-part installed app version."
                },
                {
                  "name": "publishedAs",
                  "type": "string",
                  "description": "Global, PTE or Dev."
                }
              ]
            }
          ]
        },
        {
          "name": "environment",
          "type": "object",
          "description": "The environment and company of the call. Always present.",
          "children": [
            {
              "name": "name",
              "type": "string",
              "description": "The environment name."
            },
            {
              "name": "entraTenantId",
              "type": "string",
              "description": "The Entra tenant id (GUID); empty when it cannot be read."
            },
            {
              "name": "companyId",
              "type": "string",
              "description": "The company id (GUID)."
            },
            {
              "name": "companyName",
              "type": "string",
              "description": "The company name."
            },
            {
              "name": "companyDisplayName",
              "type": "string",
              "description": "The company display name."
            },
            {
              "name": "isSaaS",
              "type": "boolean",
              "description": "True in Business Central online."
            },
            {
              "name": "isOnPremises",
              "type": "boolean",
              "description": "True on premises."
            },
            {
              "name": "isProduction",
              "type": "boolean",
              "description": "True in a production environment."
            },
            {
              "name": "isSandbox",
              "type": "boolean",
              "description": "True in a sandbox."
            }
          ]
        },
        {
          "name": "user",
          "type": "object",
          "description": "The signed-in user. Null when the caller may not read the User table.",
          "children": [
            {
              "name": "userSecurityId",
              "type": "string",
              "description": "The user security id (GUID)."
            },
            {
              "name": "userName",
              "type": "string",
              "description": "The user name."
            },
            {
              "name": "fullName",
              "type": "string",
              "description": "The full name."
            },
            {
              "name": "contactEmail",
              "type": "string",
              "description": "The contact email."
            },
            {
              "name": "authenticationEmail",
              "type": "string",
              "description": "The authentication email."
            }
          ]
        },
        {
          "name": "personalization",
          "type": "object",
          "description": "The personalization of the user. Null when it cannot be read. languageId is the session LCID to pass as lcid on later calls.",
          "children": [
            {
              "name": "profileId",
              "type": "string",
              "description": "The profile."
            },
            {
              "name": "languageId",
              "type": "integer",
              "description": "The Windows language id of the user: the LCID to pass on later calls."
            },
            {
              "name": "localeId",
              "type": "integer",
              "description": "The Windows locale id."
            },
            {
              "name": "company",
              "type": "string",
              "description": "The company the user works in."
            },
            {
              "name": "timeZone",
              "type": "string",
              "description": "The time zone."
            }
          ]
        },
        {
          "name": "sessionSourceApproval",
          "type": "object",
          "description": "How sessions from a new source are approved for this user.",
          "children": [
            {
              "name": "approvalType",
              "type": "string",
              "description": "Manual or Automatic."
            },
            {
              "name": "requiresApproval",
              "type": "boolean",
              "description": "True when a new session source needs manual approval. Help messages stay callable meanwhile."
            }
          ]
        },
        {
          "name": "userSetup",
          "type": "object",
          "description": "The Business Central User Setup row of the user. Null when there is none or it cannot be read.",
          "children": [
            {
              "name": "userId",
              "type": "string",
              "description": "The user id."
            },
            {
              "name": "salesPurchCode",
              "type": "string",
              "description": "The salesperson/purchaser code."
            },
            {
              "name": "approverId",
              "type": "string",
              "description": "The approver."
            },
            {
              "name": "salesRespCtrFilter",
              "type": "string",
              "description": "The sales responsibility center filter."
            },
            {
              "name": "purchaseRespCtrFilter",
              "type": "string",
              "description": "The purchase responsibility center filter."
            },
            {
              "name": "serviceRespCtrFilter",
              "type": "string",
              "description": "The service responsibility center filter."
            },
            {
              "name": "allowPostingFrom",
              "type": "string",
              "description": "The first posting date allowed, YYYY-MM-DD, or empty."
            },
            {
              "name": "allowPostingTo",
              "type": "string",
              "description": "The last posting date allowed, YYYY-MM-DD, or empty."
            },
            {
              "name": "timeSheetAdmin",
              "type": "boolean",
              "description": "True for a time sheet administrator."
            },
            {
              "name": "email",
              "type": "string",
              "description": "The email on User Setup."
            }
          ]
        },
        {
          "name": "approvalSetup",
          "type": "object",
          "description": "The approval fields of the User Setup row. Null when there is none.",
          "children": [
            {
              "name": "approverId",
              "type": "string",
              "description": "The approver."
            },
            {
              "name": "approvalAdministrator",
              "type": "boolean",
              "description": "True for an approval administrator."
            },
            {
              "name": "unlimitedSalesApproval",
              "type": "boolean",
              "description": "True when the user may approve any sales amount."
            },
            {
              "name": "unlimitedPurchaseApproval",
              "type": "boolean",
              "description": "True when the user may approve any purchase amount."
            },
            {
              "name": "unlimitedRequestApproval",
              "type": "boolean",
              "description": "True when the user may approve any request amount."
            },
            {
              "name": "salesAmountApprovalLimit",
              "type": "integer",
              "description": "The sales approval limit."
            },
            {
              "name": "purchaseAmountApprovalLimit",
              "type": "integer",
              "description": "The purchase approval limit."
            },
            {
              "name": "requestAmountApprovalLimit",
              "type": "integer",
              "description": "The request approval limit."
            },
            {
              "name": "substitute",
              "type": "string",
              "description": "The substitute approver."
            }
          ]
        },
        {
          "name": "notificationSetup",
          "type": "array",
          "description": "One entry per notification type the user has set up, or the default set-up (blank user) when the user has none. Null when nothing is set up or when the caller may not read the Notification Setup table.",
          "children": [
            {
              "name": "notificationType",
              "type": "string",
              "description": "The notification type, e.g. New Record."
            },
            {
              "name": "notificationMethod",
              "type": "string",
              "description": "How it is sent, e.g. Email."
            },
            {
              "name": "recurrence",
              "type": "string",
              "description": "Only when a schedule exists: how often."
            },
            {
              "name": "time",
              "type": "string",
              "description": "Only when a schedule exists: the time of day."
            },
            {
              "name": "dailyFrequency",
              "type": "string",
              "description": "Only when a schedule exists: the frequency within the day by its English name (Weekday or Daily), the same in every language."
            }
          ]
        },
        {
          "name": "resource",
          "type": "object",
          "description": "The linked resource: Resource No. of the Bifrost user setup, else the resource owned by the user (time sheet owner). Null when none.",
          "children": [
            {
              "name": "no",
              "type": "string",
              "description": "The resource number."
            },
            {
              "name": "name",
              "type": "string",
              "description": "The name."
            },
            {
              "name": "type",
              "type": "string",
              "description": "The resource type."
            }
          ]
        },
        {
          "name": "salesperson",
          "type": "object",
          "description": "The linked salesperson/purchaser: Salesperson Code of the Bifrost user setup, else the code on User Setup. Null when none.",
          "children": [
            {
              "name": "code",
              "type": "string",
              "description": "The salesperson/purchaser code."
            },
            {
              "name": "name",
              "type": "string",
              "description": "The name."
            },
            {
              "name": "email",
              "type": "string",
              "description": "The email."
            },
            {
              "name": "phoneNo",
              "type": "string",
              "description": "The phone number."
            }
          ]
        },
        {
          "name": "employee",
          "type": "object",
          "description": "The linked employee: Employee No. of the Bifrost user setup, else the employee of the user's resource. The answer does not include socialSecurityNo. Null when none.",
          "children": [
            {
              "name": "no",
              "type": "string",
              "description": "The employee number."
            },
            {
              "name": "firstName",
              "type": "string",
              "description": "The first name."
            },
            {
              "name": "lastName",
              "type": "string",
              "description": "The last name."
            },
            {
              "name": "email",
              "type": "string",
              "description": "The email."
            },
            {
              "name": "phoneNo",
              "type": "string",
              "description": "The phone number."
            },
            {
              "name": "jobTitle",
              "type": "string",
              "description": "The job title."
            },
            {
              "name": "managerNo",
              "type": "string",
              "description": "The employee number of the manager."
            },
            {
              "name": "resourceNo",
              "type": "string",
              "description": "The linked resource."
            }
          ]
        },
        {
          "name": "manager",
          "type": "object",
          "description": "The employee named as manager of the employee. Null when there is none.",
          "children": [
            {
              "name": "no",
              "type": "string",
              "description": "The employee number."
            },
            {
              "name": "firstName",
              "type": "string",
              "description": "The first name."
            },
            {
              "name": "lastName",
              "type": "string",
              "description": "The last name."
            },
            {
              "name": "email",
              "type": "string",
              "description": "The email."
            },
            {
              "name": "phoneNo",
              "type": "string",
              "description": "The phone number."
            },
            {
              "name": "jobTitle",
              "type": "string",
              "description": "The job title."
            }
          ]
        },
        {
          "name": "companyInfo",
          "type": "object",
          "description": "The Company Information record. Null when the caller may not read it.",
          "children": [
            {
              "name": "name",
              "type": "string",
              "description": "The company name."
            },
            {
              "name": "name2",
              "type": "string",
              "description": "The second name line."
            },
            {
              "name": "address",
              "type": "string",
              "description": "The address."
            },
            {
              "name": "city",
              "type": "string",
              "description": "The city."
            },
            {
              "name": "postCode",
              "type": "string",
              "description": "The post code."
            },
            {
              "name": "countryRegionCode",
              "type": "string",
              "description": "The country/region code."
            },
            {
              "name": "phoneNo",
              "type": "string",
              "description": "The phone number."
            },
            {
              "name": "email",
              "type": "string",
              "description": "The email."
            },
            {
              "name": "homePage",
              "type": "string",
              "description": "The home page."
            },
            {
              "name": "vatRegistrationNo",
              "type": "string",
              "description": "The VAT registration number."
            },
            {
              "name": "registrationNo",
              "type": "string",
              "description": "The registration number."
            }
          ]
        },
        {
          "name": "warehouseLocations",
          "type": "array",
          "description": "The locations the user works in as a warehouse employee. Null when there are none.",
          "children": [
            {
              "name": "locationCode",
              "type": "string",
              "description": "The location."
            },
            {
              "name": "default",
              "type": "boolean",
              "description": "True for the default location."
            },
            {
              "name": "adcsUser",
              "type": "boolean",
              "description": "True for an ADCS user."
            }
          ]
        },
        {
          "name": "responsibilityCenters",
          "type": "object",
          "description": "The responsibility center filters of the User Setup row. Null when all three are empty.",
          "children": [
            {
              "name": "salesRespCtrFilter",
              "type": "string",
              "description": "The sales responsibility center filter."
            },
            {
              "name": "purchaseRespCtrFilter",
              "type": "string",
              "description": "The purchase responsibility center filter."
            },
            {
              "name": "serviceRespCtrFilter",
              "type": "string",
              "description": "The service responsibility center filter."
            }
          ]
        },
        {
          "name": "dueFromToOwner",
          "type": "object",
          "description": "The G/L account named in G/L Account No. of the Bifrost user setup, with its balance up to the work date (balanceAtDate and netChange are left out for a caller with any Read or Both Field Access row). An object, not a list. Null when no account is set.",
          "children": [
            {
              "name": "glAccountNo",
              "type": "string",
              "description": "The G/L account number."
            },
            {
              "name": "name",
              "type": "string",
              "description": "The account name."
            },
            {
              "name": "balanceAtDate",
              "type": "number",
              "description": "The balance up to the work date."
            },
            {
              "name": "netChange",
              "type": "number",
              "description": "The net change up to the work date."
            }
          ]
        },
        {
          "name": "customer",
          "type": "object",
          "description": "The customer linked in the Bifrost user setup, with its balances (left out for a caller with any Read or Both Field Access row). Null when none.",
          "children": [
            {
              "name": "no",
              "type": "string",
              "description": "The customer number."
            },
            {
              "name": "name",
              "type": "string",
              "description": "The name."
            },
            {
              "name": "address",
              "type": "string",
              "description": "The address."
            },
            {
              "name": "city",
              "type": "string",
              "description": "The city."
            },
            {
              "name": "postCode",
              "type": "string",
              "description": "The post code."
            },
            {
              "name": "phoneNo",
              "type": "string",
              "description": "The phone number."
            },
            {
              "name": "email",
              "type": "string",
              "description": "The email."
            },
            {
              "name": "creditLimitLCY",
              "type": "number",
              "description": "The credit limit in local currency."
            },
            {
              "name": "balanceLCY",
              "type": "number",
              "description": "The balance in local currency."
            },
            {
              "name": "balanceDueLCY",
              "type": "number",
              "description": "The part of balanceLCY that is past its due date: the entries whose due date is before today. Entries due today or later are not in it."
            }
          ]
        },
        {
          "name": "vendor",
          "type": "object",
          "description": "The vendor linked in the Bifrost user setup, with its balances (left out for a caller with any Read or Both Field Access row). Null when none.",
          "children": [
            {
              "name": "no",
              "type": "string",
              "description": "The vendor number."
            },
            {
              "name": "name",
              "type": "string",
              "description": "The name."
            },
            {
              "name": "address",
              "type": "string",
              "description": "The address."
            },
            {
              "name": "city",
              "type": "string",
              "description": "The city."
            },
            {
              "name": "postCode",
              "type": "string",
              "description": "The post code."
            },
            {
              "name": "phoneNo",
              "type": "string",
              "description": "The phone number."
            },
            {
              "name": "email",
              "type": "string",
              "description": "The email."
            },
            {
              "name": "balanceLCY",
              "type": "number",
              "description": "The balance in local currency."
            },
            {
              "name": "balanceDueLCY",
              "type": "number",
              "description": "The part of balanceLCY that is past its due date: the entries whose due date is before today. Entries due today or later are not in it."
            }
          ]
        },
        {
          "name": "contact",
          "type": "object",
          "description": "The contact linked in the Bifrost user setup. Null when none.",
          "children": [
            {
              "name": "no",
              "type": "string",
              "description": "The contact number."
            },
            {
              "name": "name",
              "type": "string",
              "description": "The name."
            },
            {
              "name": "address",
              "type": "string",
              "description": "The address."
            },
            {
              "name": "city",
              "type": "string",
              "description": "The city."
            },
            {
              "name": "postCode",
              "type": "string",
              "description": "The post code."
            },
            {
              "name": "phoneNo",
              "type": "string",
              "description": "The phone number."
            },
            {
              "name": "email",
              "type": "string",
              "description": "The email."
            },
            {
              "name": "type",
              "type": "string",
              "description": "Company or Person."
            },
            {
              "name": "companyNo",
              "type": "string",
              "description": "The company contact."
            },
            {
              "name": "companyName",
              "type": "string",
              "description": "Its name."
            }
          ]
        },
        {
          "name": "systemPrompt",
          "type": "string",
          "description": "The system prompt the administrator stored on the Bifrost user setup of this user. Null when there is none or it is empty. Treat it as behavioural instructions for this user in this company."
        },
        {
          "name": "unreadNotifications",
          "type": "array",
          "description": "One entry per unread notification thread of the user; an empty array when none. Surface it. Read the content with User.Notification.Get.",
          "children": [
            {
              "name": "sender",
              "type": "string",
              "description": "The user id of the sender."
            },
            {
              "name": "subject",
              "type": "string",
              "description": "The subject."
            },
            {
              "name": "threadId",
              "type": "string",
              "description": "The thread id (GUID)."
            }
          ]
        },
        {
          "name": "pendingApprovals",
          "type": "array",
          "description": "The open approval entries waiting for the user. Null when the user may not read approval entries or has none. Act on them with Document.Approval.Me.",
          "children": [
            {
              "name": "documentType",
              "type": "string",
              "description": "The approval document type, e.g. Invoice."
            },
            {
              "name": "documentNo",
              "type": "string",
              "description": "The document number."
            },
            {
              "name": "amountLCY",
              "type": "string",
              "description": "The amount in local currency, culture-invariant."
            },
            {
              "name": "dueDate",
              "type": "string",
              "description": "The due date, YYYY-MM-DD."
            }
          ]
        },
        {
          "name": "canUpdateCompanyMemory",
          "type": "boolean",
          "description": "True when the user may write company memory."
        },
        {
          "name": "canSendAndCancelApprovalRequests",
          "type": "boolean",
          "description": "True when the user may send and cancel approval requests."
        },
        {
          "name": "telegramChatId",
          "type": "string",
          "description": "Telegram chat ID from the calling user's Bifrost user setup; an empty string when none is set."
        }
      ],
      "whenNull": "A section is null when the caller may not read its source table (Business Central permissions, or the table restriction list that Data.Records.Get also applies), when no field of it is left after Field Access, or when the record it links to is not set up or not found. A field the caller has a Read or Both row for in Bifrost Field Access is left out of its section. The shape of a section that is present is the one listed, minus the fields left out."
    },
    "errors": [
      {
        "code": "BusinessCentralError",
        "error": "Unsupported specification version {version}. Expected version 1.0.",
        "when": "The message names a specification version other than 1.0.",
        "fix": "Send specification version 1.0, which is the default."
      }
    ],
    "effect": {
      "effect": "read",
      "changes": "Nothing, except that the first call by a user creates that user's own Bifrost user setup row (and evaluates its charge type). Later calls change nothing.",
      "idempotent": true,
      "preconditions": [
        "Fields the caller has a Read or Both row for in Bifrost Field Access are left out of their sections without an error.",
        "For a caller with any Read or Both row, the FlowField figures (customer, vendor and G/L balances) are left out."
      ]
    },
    "metering": {
      "chargeable": false,
      "exemptReason": "Help.* message types of Origo applications are free."
    },
    "related": [
      {
        "name": "Help.Bifrost.Get",
        "useInsteadWhen": "You start a session and want the directory of the Help types and the how-to guide."
      },
      {
        "name": "User.Notification.Get",
        "useInsteadWhen": "unreadNotifications has entries and you want to read them."
      },
      {
        "name": "Document.Approval.Me",
        "useInsteadWhen": "pendingApprovals has entries and you want to act on them."
      },
      {
        "name": "Memory.User.Get",
        "useInsteadWhen": "You want the memory the user has stored."
      },
